% -----------------------------------------------------------------
%  Grid dimensions
n_rows(N) :- N = #count{ R : input(R, _, _) }.
n_cols(M) :- M = #count{ C : input(_, C, _) }.
row(0..N-1)   :- n_rows(N).
col(0..M-1)   :- n_cols(M).

output_cell(R, C) :- row(R), col(C).

% -----------------------------------------------------------------
%  Exactly one colour must be chosen for each output cell
1 { output(R, C, Color) : color(Color) } 1 :- output_cell(R, C).

% -----------------------------------------------------------------
%  Transformation rule – colour = number of non‑zero neighbours
%  (the 3×3 neighbourhood, the cell itself included)
output(R, C, Count) :-
    Count = #count{
        dr, dc : 
            dr = -1 ; dc = -1 ;
            dr = -1 ; dc = 0 ;
            dr = -1 ; dc = 1 ;
            dr = 0  ; dc = -1 ;
            dr = 0  ; dc = 1  ;
            dr = 1  ; dc = -1 ;
            dr = 1  ; dc = 0  ;
            dr = 1  ; dc = 1 ,
            input(R+dr, C+dc, Color),
            color(Color),
            color != 0
    }.

#show output/3.

